{
  "name": "光纤光谱仪",
  "name_en": "Fiber Optic Spectrometer",
  "manufacturer": "",
  "description": "这是一种用于采集光谱信号的光纤光谱仪，可在设定积分时间后测量样品或光源的强度随波长分布。实验室中常用于发射光谱、吸收光谱、荧光光谱及一般光学表征。",
  "description_en": "This is a fiber optic spectrometer used to acquire optical spectra by measuring intensity as a function of wavelength with a configurable integration time. In laboratories it is commonly used for emission, absorption, fluorescence, and general optical characterization.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开光谱仪连接。",
      "description_en": "Open the spectrometer connection."
    },
    {
      "action_name": "auto-close",
      "description": "关闭光谱仪连接。",
      "description_en": "Close the spectrometer connection."
    },
    {
      "action_name": "auto-readSpectrum",
      "description": "按指定积分时间采集一次光谱，并保存到文件。",
      "description_en": "Acquire a spectrum with the specified integration time and save it to a file."
    },
    {
      "action_name": "auto-loadFile",
      "description": "加载已保存的光谱文件。",
      "description_en": "Load a previously saved spectrum file."
    }
  ],
  "tag_hints": [
    "fiber optic spectroscopy",
    "optical spectrum acquisition",
    "emission spectroscopy",
    "absorption measurement",
    "fluorescence measurement",
    "integration time control"
  ]
}

